const defaultStops = (name) => [
  { name: `${name} main landmark`, time: '08:30–10:00', duration: '1.5 hours', travelFromPrevious: 'Arrival / local transfer' },
  { name: `${name} heritage or cultural quarter`, time: '10:30–12:00', duration: '1.5 hours', travelFromPrevious: 'Approx. 15–30 min local transfer' },
  { name: `${name} local market or food stop`, time: '16:00–17:30', duration: '1.5 hours', travelFromPrevious: 'Approx. 15–30 min local transfer' }
];

const indiaDestinations = raw.map((r, idx) => {
  const [name, state, category, budget, days, lat, lon, bestMonths, bestTime, specialty, specialtyWhere, stopsText, safety] = r;
  const stops = stopsText.split(';').map((s, i) => {
    const [title, time, duration, travelFromPrevious] = s.split('~');
    return { name: title, time, duration, travelFromPrevious };
  });
  return {
    id: `in-${idx + 1}`, name, state, country: 'India', category, budget, days, lat, lon,
    description: `${category} experiences in ${name}, with local food, culture and memorable sights.`,
    emoji: ({Culture:'🏛️',Heritage:'🏛️','City & food':'🍲','Food & culture':'🍛',Spiritual:'🪔','Spiritual & food':'🪔',Nature:'🌿','Nature & trekking':'🥾','Hill station':'⛰️',Adventure:'🧭','Adventure & nature':'🥾','Wildlife':'🐅','Wildlife & birding':'🦜','Coastal':'🌊','Coastal & culture':'🌊','Backwaters':'🛶','Island & nature':'🏝️','Mountain & culture':'🏔️','Heritage & crafts':'🎨','Heritage & food':'🍲','Desert':'🏜️','Desert & culture':'🏜️'})[category] || '📍',
    bestMonths, bestTime, specialty, specialtyWhere, stops: stops.length ? stops : defaultStops(name), safety,
    estimatedTotal: budget * days,
    hotelSearchUrl: `https://www.google.com/travel/search?q=${encodeURIComponent(`hotels in ${name}`)}`,
    transportSearchUrl: `https://www.google.com/travel/search?q=${encodeURIComponent(`transport to ${name}`)}`,
    mapUrl: `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(name)}`
  };
});

const uniqueDestinations = indiaDestinations.filter((d, i, all) => all.findIndex(other => other.name === d.name) === i);
module.exports = { indiaDestinations: uniqueDestinations };
